window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"e9sStKXu0J8","speaker":"Alar Karis","role":"President","country":"Estonia","region":"Europe","url":"https://www.youtube.com/watch?v=e9sStKXu0J8","date":"20260923","title":"🇪🇪 Estonia - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1160,"words":2396,"counts":{"claims":31,"promises":3,"attacks":4},"topics":[{"topic":"Ukraine","share":0.278,"seconds":323},{"topic":"UN reform","share":0.2497,"seconds":290},{"topic":"Gaza","share":0.1142,"seconds":132},{"topic":"Russia","share":0.1141,"seconds":132},{"topic":"Estonia emissions","share":0.0664,"seconds":77},{"topic":"Estonia AI","share":0.0625,"seconds":72},{"topic":"UN human rights","share":0.062,"seconds":72},{"topic":"AI education","share":0.0532,"seconds":62}],"timeline":[[5,76,"UN reform"],[77,140,"Ukraine"],[141,218,"Estonia emissions"],[219,281,"Ukraine"],[282,347,"Russia"],[348,416,"Russia"],[418,483,"Ukraine"],[484,551,"Gaza"],[553,618,"Gaza"],[620,686,"UN reform"],[687,750,"UN reform"],[752,842,"UN reform"],[842,914,"UN human rights"],[916,977,"Ukraine"],[978,1049,"Ukraine"],[1051,1112,"AI education"],[1113,1186,"Estonia AI"],[1187,1223,null]],"stances":{"UN reform":"Alar Karis states that while he believes in the UN's promise, the current world order is at a profound turning point and not improving.","Ukraine":"Alar Karis states that aggression and conflicts are becoming the new normal, causing suffering for millions of people in Ukraine, Gaza, Sudan, Haiti, and Myanmar.","Estonia emissions":"Alar Karis states that Estonia has reduced its emissions by 66% over the past 35 years while transforming its energy system.","Russia":"Alar Karis states that Russia's actions violate sovereignty and threaten global food security, arguing that condemnation alone is insufficient and collective action is needed to force Russia into negotiations.","Gaza":"Alar Karis states that Estonia is concerned about the situation in the West Bank and Gaza, calls for upholding international humanitarian law, ensures safe access for aid, and supports a two-state solution.","UN human rights":"Alar Karis states that Estonia believes respect for human rights is essential for peace and security, supports the UN human rights system, and highlights Estonia's role in the Human Rights Council.","AI education":"Alar Karis states that AI should serve people securely and reliably, emphasizing its role in advancing safe, inclusive, and child-centered learning while empowering rather than replacing teaching.","Estonia AI":"Alar Karis states that Estonia has shared its digitalization experience with 150 countries and nominated a candidate for the ITU development bureau to ensure AI creates equal opportunities."},"claims":[{"t":36,"quote":"last year, speaking from this podium, I described the United Nations as an idea of a better world.","topic":"UN reform","kind":"fact"},{"t":44,"quote":"It is a carefully crafted agreement to safeguard peace and security, promote development, and uphold human rights.","topic":"UN reform","kind":"fact"},{"t":106,"quote":"Millions of people are suffering in Ukraine, Gaza, Sudan, Hayiti, Myanmar.","topic":"Ukraine","kind":"fact"},{"t":128,"quote":"Over the past three years, more than 1,000 humanitarian workers have lost their lives.","topic":"Ukraine","kind":"number"},{"t":152,"quote":"We have reduced our emissions by 66% over the past 35 years while transforming our energy system.","topic":"Estonia emissions","kind":"number"},{"t":257,"quote":"For more than 12 years ago, since the illegal annction of Crimea and occupation of eastern Ukraine in 2014, a permanent member of the Security Council, the Russian Federation, has been perpetrating a war of aggression at the very heart of Europe.","topic":"Ukraine","kind":"fact"},{"t":301,"quote":"by increasingly targeting Ukraine's Black Sea ports, commercial shipping, grain infrastructure, and alternative export routes, Russia is putting global food security at grave risk.","topic":"Russia","kind":"fact"},{"t":320,"quote":"Russia's actions have been condemned by a large majority of this assembly.","topic":"Russia","kind":"fact"},{"t":387,"quote":"Estonia is doing its part. We have completed all national procedures and taken the lead in discussing discussions in Stburg to establish the special tribunal as soon as possible.","topic":"Russia","kind":"self_credit"},{"t":400,"quote":"A UN member state whose armed forces have been repeatedly cited in the UN secretar's report for grave violations against Shindron and conflict related sexual violence should have been no place in UN peace peacekeeping operations.","topic":"Russia","kind":"fact"},{"t":446,"quote":"Estonia together with its partners have worked closely to support Ukraine's cyber security and resilience in responding to evolving threats through the Italian mechanism and the IT Estonone is also proud to be hosting the Ukraine recovery conference in 2027 organized in cooperation with our closest friends in the Nordic Baltic Building on the outcomes of early conferences, next year's event will be advancing its practical terms, long-term international support for Ukraine and its recovery.","topic":"Ukraine","kind":"fact"},{"t":511,"quote":"The situation in the West Bank and Gaza remains of great concern.","topic":"Gaza","kind":"fact"},{"t":522,"quote":"Estonia has consistently called for upholding international humanitarian law and ensuring safe, rapid and unhindered access of humanitarian aid for those in","topic":"Gaza","kind":"fact"},{"t":553,"quote":"We have provided food aid to hospitals in Gaza and stand ready to offer our digital transition expertise in its future reconstruction.","topic":"Gaza","kind":"fact"},{"t":564,"quote":"Estonia has consistently condemned the attack by Iran against our close partners, the Gulf States, and has shown its readiness to contribute to ensuring freedom of navigation in the region.","topic":"Gaza","kind":"fact"},{"t":635,"quote":"Estonia supports the systemwide reform of UN80 and humanitarian reset which are both well underway and have already delivered some encouraging results.","topic":"UN reform","kind":"fact"},{"t":680,"quote":"Estonian humanitarian organizations are already testing these solutions from Palestine to Sutan.","topic":"UN reform","kind":"fact"},{"t":703,"quote":"This year, the United Nations is set to make arguably one of its most consequential decisions, the selection and appointment of its next secretary","topic":"UN reform","kind":"fact"},{"t":743,"quote":"Estonia also feels that after 81 years, it is time for organization to be led by a woman.","topic":"UN reform","kind":"fact"},{"t":787,"quote":"We have not seen unified and decisive council action on Ukraine, Sudan or in The use of the veto and the threat of its use continue to loom over the council and paralyze any of its attempts to take action.","topic":"UN reform","kind":"fact"},{"t":805,"quote":"Estonia has strongly advocated for permanent members to refrain from vetoing resolutions aimed at ending mass atrocities in line with the France Mexico proposal and the ACT code of It is also important to call on the security council members to start fully implementing article 273 of the charter once again and to abstain in cases where members of a council are a party to a The General Assembly resolution, United for Peace, gives the most","topic":"UN reform","kind":"self_credit"},{"t":902,"quote":"Estonia is a member of the United Nations Human Rights Council for a period from 2026 to 2028 and is currently serving as vice president of the council.","topic":"UN human rights","kind":"fact"},{"t":916,"quote":"As a country ranked among the world's top three for press freedom, we are committed to promoting media freedom, protecting journalists, and enhancing media literacy.","topic":"Ukraine","kind":"fact"},{"t":938,"quote":"Together with New Zealand and Colombia, Estonia is leading negotiations on the human rights council on the resolution on preventing maternal mortality and mobility.","topic":"Ukraine","kind":"fact"},{"t":960,"quote":"One of the gravest aspects of Russia's war against Ukraine is a mass deportation and forced transfer of Ukrainian children, which is systematic and deliberate attempt to raise their Ukrainian identity.","topic":"Ukraine","kind":"fact"},{"t":978,"quote":"We therefore reiterate the call of call of the general assembly resolution adopted on the 3rd of December 2025","topic":"Ukraine","kind":"fact"},{"t":1004,"quote":"you asked F US first lady Melania Trump for a remarkable humanitarian initiative","topic":"Ukraine","kind":"fact"},{"t":1051,"quote":"Personally, I had an honor to becoming one of the commissioners of AI for cool global commission this summer.","topic":"AI education","kind":"self_credit"},{"t":1092,"quote":"In Estonia, we have introduced a massive education innovation program we call the AI leap whose aim is to assist schools, students and teachers alike to adapt to the age of AI and foster meaningful learning.","topic":"AI education","kind":"fact"},{"t":1129,"quote":"We know for certain that digitalization, which has now been reinforced by AI, has abled our small country to grow, innovate, and connect globally.","topic":"Estonia AI","kind":"fact"},{"t":1142,"quote":"This is why we have shared our experience with 150 other countries worldwide.","topic":"Estonia AI","kind":"number"}],"promises":[{"t":535,"quote":"We remain a stable dora in UNRA and are committed to a credible political process leading to a negotiated two-state solution with Israel and Palestine living side by side in peace, security and dignity.","topic":"Gaza","kind":"promise"},{"t":928,"quote":"We will continue our strong commitment to women's rights and gender equality, including sexual and reproductive health and rights.","topic":"Ukraine","kind":"promise"},{"t":1158,"quote":"You can trust us to work to turn connectivity into lasting capability and to asssure that no country is left behind in the digital transformation.","topic":"Estonia AI","kind":"promise"}],"attacks":[{"t":266,"quote":"a permanent member of the Security Council, the Russian Federation, has been perpetrating a war of aggression at the very heart of Europe. that aggression disregards the principles of United Nation Charter to its very core.","topic":"Ukraine","target":"Russia"},{"t":282,"quote":"It violates respect of sovereignty and territorial integrity of states and prohibition of a use of force against another state.","topic":"Russia","target":"Russia"},{"t":400,"quote":"A UN member state whose armed forces have been repeatedly cited in the UN secretar's report for grave violations against Shindron and conflict related sexual violence should have been no place in UN peace peacekeeping operations.","topic":"Russia","target":"Russia"},{"t":974,"quote":"It is a war crime and a crime against humanity.","topic":"Ukraine","target":"Russia"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":5,"topic":"UN reform","text":"The assembly will now hear an address by His Excellency, Mr. Allar Caris, President of the Republic of Estonia. I request protocol to escort his excellency and invite him to address the Mr. President, excellencies, ladies and last year, speaking from this podium, I described the United Nations as an idea of a better world. It is a carefully crafted agreement to safeguard peace and security, promote development, and uphold human rights. I still believe in that promise enshrined in the United Nations charter. But the world around us is changing and not for the better. Over the past year in particular, it has become increasingly clear that the multilateral world order with the United Nations and the charter in its core is at a profound turning point."},{"t":77,"topic":"Ukraine","text":"Bradent disregard for international law and the principles of a charter reinforced by the sense of impunity too often dominates over adherence to the rule of law and cooperation between countries for a better future. Mutal dependence has come to be treated as a critical vulnerability. Aggression, wars and conflicts ris conflict is becoming the new normal. Millions of people are suffering in Ukraine, Gaza, Sudan, Hayiti, Myanmar. Sometimes we tend to forget that behind the numbers there are always human beings. Families separated, children affected, homes destroyed and lives disrupted disrupted by conflict. Over the past three years, more than 1,000 humanitarian workers have lost their lives. And beyond ongoing wars and conflicts, there is a looming crisis brought on by climate change."},{"t":141,"topic":"Estonia emissions","text":"One in which time is running out for us to act. Indeed, the time to act is now. Estonia, for example, is contributing its share. We have reduced our emissions by 66% over the past 35 years while transforming our energy system. Yes, the world is on fire. Troubles and problems are mounting before our eyes. The cooperative spirit in the international relations that emerged after San Francisco and that was clearly present after the end of the cold war is fading away. The UN is suffering because of it. But it is also true that the United Nation requires profound reforms to be able to tackle the challenges of the 21st century. As such, the question reality is reality is do we let the United Nations together with its aims and founding principles just slowly fall apart or do we start facing these challengings with a sense of common responsibility and genuinely try to reform the UN and start to use the only global framework we have in a responsible and sensible way."},{"t":219,"topic":"Ukraine","text":"The stakes are high. The choice is ours for Estonia and I believe for the great majority on UN member states. Upholding the principles of the UN charter is of vital interest. But we are also conscious that in order to for those principles to remain valid and respected, we need to invest in them as much with our words as with our actions. Ladies and gentlemen, one of the biggest tests for the UN's relevance is Russia's aggression against Ukraine. For more than 12 years ago, since the illegal annction of Crimea and occupation of eastern Ukraine in 2014, a permanent member of the Security Council, the Russian Federation, has been perpetrating a war of aggression at the very heart of Europe. that aggression disregards the principles of United Nation Charter to its very core."},{"t":282,"topic":"Russia","text":"It violates respect of sovereignty and territorial integrity of states and prohibition of a use of force against another state. The consequence of Russia's aggression, however, extend beyond Ukraine and Europe. For example, by increasingly targeting Ukraine's Black Sea ports, commercial shipping, grain infrastructure, and alternative export routes, Russia is putting global food security at grave risk. As such, this is a concern for all of us and rightly so. Russia's actions have been condemned by a large majority of this assembly. But condemnation is not enough. We need to collectively force Russia into peace in Ukraine to force into the negotiation table by raising the cost of its For this we can and should use the diverse instruments at our disposal be the economic, diplomatic or political."},{"t":348,"topic":"Russia","text":"I strongly encourage more of my fellow heads of state and government to use this occasion to call on Russia to seize its aggression. Those of you have done so already, be it the global south or north, you have my The principles of the UN charter cannot be trampled on. It is our collective task to stand up for them. We should also support the efforts of international mechanisms to document the war crimes, ensure accountability and provide assistance to those rights have been violated. Estonia is doing its part. We have completed all national procedures and taken the lead in discussing discussions in Stburg to establish the special tribunal as soon as possible. A UN member state whose armed forces have been repeatedly cited in the UN secretar's report for grave violations against Shindron and conflict related sexual violence should have been no place in UN peace peacekeeping operations."},{"t":418,"topic":"Ukraine","text":"This is a matter of ensuring that perpetrators actions have consequences, but it is equally a matter of training trust in and the integrity of UN peacekeeping. I further call on the UN to stop reflecting and instead take appropriate actions immediately. Ukraine requires assistance in defending itself, but also in rebuilding the country. Estonia together with its partners have worked closely to support Ukraine's cyber security and resilience in responding to evolving threats through the Italian mechanism and the IT Estonone is also proud to be hosting the Ukraine recovery conference in 2027 organized in cooperation with our closest friends in the Nordic Baltic Building on the outcomes of early conferences, next year's event will be advancing its practical terms, long-term international support for Ukraine and its recovery."},{"t":484,"topic":"Gaza","text":"As such, it will be a multilateral effort and example of true cooperation for international peace and My fellow leaders, while in situation Ukraine and Ukraine security that affects Estonia most directly, we are neither indifferent to nor unaffected by the impact of other wars, threats, and conflicts. The situation in the West Bank and Gaza remains of great concern. Innocent civilians and children must not bear the devastating human cost of a war. Estonia has consistently called for upholding international humanitarian law and ensuring safe, rapid and unhindered access of humanitarian aid for those in We remain a stable dora in UNRA and are committed to a credible political process leading to a negotiated two-state solution with Israel and Palestine living side by side in peace, security and dignity."},{"t":553,"topic":"Gaza","text":"We have provided food aid to hospitals in Gaza and stand ready to offer our digital transition expertise in its future reconstruction. Estonia has consistently condemned the attack by Iran against our close partners, the Gulf States, and has shown its readiness to contribute to ensuring freedom of navigation in the region. This is an issue that affects us all. We also see instrumental instrumentalization of migration as a means of exerting pressure on countries whether on the European Union eastern and southern borders or elsewhere. Irregular irregular migration is increasingly becoming a security issue and it requires a coordinated international response. Ladies and gentlemen, if we want a United Nations that is more effective in terms of decision making, more efficient in managing available resources and up to date on technological developments."},{"t":620,"topic":"UN reform","text":"We adopt at it the shared task to readjust the structure of UN United Nation around the three pillars and well as reassess how the United Nations Estonia supports the systemwide reform of UN80 and humanitarian reset which are both well underway and have already delivered some encouraging results. Now it's time to build on this momentum and to move decisively forward with reforms. We need ambition. For example, humanitarian sector along alongside stronger data harmonization could move towards a shared interoperability model that allows many system to coexist while quickly and safely exchanging data. Estonian humanitarian organizations are already testing these solutions from Palestine to Sutan."},{"t":687,"topic":"UN reform","text":"We also need determination. Above all, we need action. Action that strengthens the UN as a main actor responsible for multilateral cooperation and prepares it for future challenges. This year, the United Nations is set to make arguably one of its most consequential decisions, the selection and appointment of its next secretary As an active member of the accountability, coherence and transparency group, Estonia has stood for transparent, fair and inclusive At this challenging time for the organization, we need a strong and principled leader with an impeccable track record in championing and upholding international law, human rights, and the principles of a charter. Estonia also feels that after 81 years, it is time for organization to be led by a woman."},{"t":752,"topic":"UN reform","text":"Allow me to take this opportunity to commend and express our gratitude to our current Secretary General, Mr. Antonio Gutierrez, for his steadfast commitment to the principles of the UN charter, including his support for a just and lasting peace in Ukraine. With regard to the Security Council, it must be said that its inability to take timely and decisive decisions on some of the worst crisis we are seeing today risks rendering the United Nations We have not seen unified and decisive council action on Ukraine, Sudan or in The use of the veto and the threat of its use continue to loom over the council and paralyze any of its attempts to take action. Estonia has strongly advocated for permanent members to refrain from vetoing resolutions aimed at ending mass atrocities in line with the France Mexico proposal and the ACT code of It is also important to call on the security council members to start fully implementing article 273 of the charter once again and to abstain in cases where members of a council are a party to a The General Assembly resolution, United for Peace, gives the most"},{"t":842,"topic":"UN human rights","text":"representative and democratic body of a United Nation a toolbox to act on matters related to international peace and security when the council is unable to deliver. In concert, we must reinforce the role of a general assembly when it comes to peace and security. And this will help us in collectively finding solutions where the council is powerless. Ladies and gentlemen, Estonia firmly believes that respect of human rights is a prerequisite for peace, security, and prosperity. We stand firmly behind the United Nations human rights system and will continue to defend and strengthen it. As one of the first supporters of a global alliance for human rights, Estonia feels that human rights should once again be at the center of a world we choose to build. Estonia is a member of the United Nations Human Rights Council for a period from 2026 to 2028 and is currently serving as vice president of the council."},{"t":916,"topic":"Ukraine","text":"As a country ranked among the world's top three for press freedom, we are committed to promoting media freedom, protecting journalists, and enhancing media literacy. We will continue our strong commitment to women's rights and gender equality, including sexual and reproductive health and rights. Together with New Zealand and Colombia, Estonia is leading negotiations on the human rights council on the resolution on preventing maternal mortality and mobility. Maternal survival is a question of justice and human rights, not only healthcare. Estonia stands firmly for ending all forms of violence against children. One of the gravest aspects of Russia's war against Ukraine is a mass deportation and forced transfer of Ukrainian children, which is systematic and deliberate attempt to raise their Ukrainian identity. It is a war crime and a crime against humanity."},{"t":978,"topic":"Ukraine","text":"We therefore reiterate the call of call of the general assembly resolution adopted on the 3rd of December 2025 and demand that the Russian Federation ensure the safe, immediate and unconditional return of all forcibly transferred and deported Ukrainian children. We thank all of our international partners working to reunite these children with their families. In particular, you asked F US first lady Melania Trump for a remarkable humanitarian initiative. Ladies and gentlemen, artificial intelligence is yet to stay and to be used to assist us as has been the case with every major technology throughout human history. Like any new technology, AI poses risks and bring challenges. But with knowledge, wisdom and unity, we can put it use in the service of humanity. As a co-chair of a first UN global dialogue on AI governance alongside with El Salvador, Estonia has proudly brought its knowledge and experience in service of the UN and its member states."},{"t":1051,"topic":"AI education","text":"Personally, I had an honor to becoming one of the commissioners of AI for cool global commission this summer. For me, this role means both trust and responsibility to help ensure that AI serves people, that its use is secure and reliable, and that its benefits reach as many countries and communities as possible. As a current president of a UNICEF executive board, Estonia has been paying particular attention to the topic of innovation in education, notably how to advance in the responsible way safe, inclusive and child centered learning with a support of AI. In Estonia, we have introduced a massive education innovation program we call the AI leap whose aim is to assist schools, students and teachers alike to adapt to the age of AI and foster meaningful learning. Artificial intelligence should empower teaching and learning rather than replace them."},{"t":1113,"topic":"Estonia AI","text":"Under the opaces of the United Nation, notably through close cooperation with UNICEF, we are bringing our experience and best practice to the global scene, ensuring that AI creates equal opportunities for all humanity. We know for certain that digitalization, which has now been reinforced by AI, has abled our small country to grow, innovate, and connect globally. This is why we have shared our experience with 150 other countries worldwide. And this is also why Estonia has nominated a candidate for the position of director of ITU development bureau. You can trust us to work to turn connectivity into lasting capability and to asssure that no country is left behind in the digital transformation. We hope to count on your valuable support. Ladies and gentlemen, the very fact that we are gathered here today should give us hope that we still share a commitment to the United Nation Charter and to multilateral cooperation."},{"t":1187,"topic":null,"text":"Otherwise, why would we keep coming to New York year after year? Let us preserve that matters, adapt where we must and design the future together. We have a choice to shape change or to be shaped by it. And we can only shape it if we stand together. Thank you very much for your On behalf of the assembly, I wish to thank the president of the Republic of Estonia. Yeah."}],"compare":[{"topic":"Russia-Ukraine War","share":0.3921,"mean":0.0334,"rank":4,"others":44},{"topic":"UN & its reform","share":0.3117,"mean":0.2042,"rank":41,"others":170},{"topic":"Israel–Palestine","share":0.1142,"mean":0.0521,"rank":29,"others":76},{"topic":"Artificial Intelligence","share":0.0532,"mean":0.0505,"rank":72,"others":83}]};
